/// Bundled demo receipts (generated by tool/generate_sample_receipts.py) so the
/// web demo can be tried without a camera or real receipts.
class SampleReceipt {
  const SampleReceipt(this.label, this.assetPath);

  final String label;
  final String assetPath;
}

